// FicheConges.js — v2026-07-21a — signature AF + date du jour + cadre DECISION décalé
import React, { useState, useEffect } from 'react'
import { useSignature } from './useSignature'
import { PDFDocument, rgb, StandardFonts } from 'pdf-lib'
import { supabase } from '../lib/supabase'

const LOGO_B64 = ""

function b64ToBytes(b64) {
  const bin = atob(b64); const arr = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i)
  return arr
}
function hexToRgb(hex) {
  const r = parseInt(hex.slice(1,3),16)/255
  const g = parseInt(hex.slice(3,5),16)/255
  const b = parseInt(hex.slice(5,7),16)/255
  return rgb(r,g,b)
}
function fmtDate(iso) {
  if (!iso) return ''
  const [y,m,d] = iso.split('T')[0].split('-')
  return `${d}/${m}/${y}`
}
function nbJoursOuvres(debut, fin) {
  let count = 0
  const d = new Date(debut)
  const f = new Date(fin)
  while (d <= f) {
    count++
    d.setDate(d.getDate() + 1)
  }
  return count
}

export default function FicheConges({ profile, onClose, dateDebutInit, dateFinInit, congeRelaisInit, pdfSeulement }) {
  const [enfants, setEnfants] = useState([])
  const [afProfiles, setAfProfiles] = useState([])
  const [form, setForm] = useState({
    dateDebut: dateDebutInit || '',
    dateFin: dateFinInit || '',
    dateDemandeAffichee: new Date().toISOString().slice(0, 10),
    notes: '',
  })
  const [relaisParEnfant, setRelaisParEnfant] = useState(() => {
    if (!congeRelaisInit) return {}
    const init = {}
    Object.entries(congeRelaisInit).forEach(([enfantId, relais]) => {
      if (relais?.afId) init[enfantId] = relais.afId
    })
    return init
  })
  const [relais2ParEnfant, setRelais2ParEnfant] = useState({})
  const [saving, setSaving] = useState(false)
  const [toast, setToast] = useState('')
  const { getSignatureBytes, SignatureModal } = useSignature(profile)

  useEffect(() => {
    if (!profile?.id) return
    // Charger les enfants de l'AF
    supabase.from('enfants').select('id,prenom,nom,territoire,af_principal_id,referent:referent_id(nom,prenom)')
      .eq('af_principal_id', profile.id)
      .then(({ data }) => { if (data) setEnfants(data) })
    // Charger les AF pour le relais
    supabase.from('profiles').select('id,nom,prenom').eq('role', 'af')
      .then(({ data }) => { if (data) setAfProfiles(data.filter(a => a.id !== profile.id)) })
  }, [profile])

  const nbJours = form.dateDebut && form.dateFin
    ? nbJoursOuvres(form.dateDebut, form.dateFin)
    : 0

  const secteurLabel = profile?.secteur === 'Nord' ? 'Nord'
    : profile?.secteur === 'Sud' ? 'Sud'
    : profile?.secteur === 'Ouest' ? 'Ouest' : ''

  function getReferent(enfant) {
    // On n'a pas le référent ici, on met un champ vide
    return ''
  }

  async function soumettreCompteurEtPDF() {
    setSaving(true)
    try {
      // Insert compteur congés
      const dateDebutISO = new Date(`${dateDebutInit}T00:00:00`).toISOString()
      const dateFinISO = new Date(`${dateFinInit}T23:59:00`).toISOString()
      const nb = nbJoursOuvres(dateDebutInit, dateFinInit)
      await supabase.from('conges').insert({
        af_id: profile.id,
        date_debut: dateDebutISO,
        date_fin: dateFinISO,
        nb_jours: nb,
        statut: 'en_attente',
        notes: '',
      })
      // Notification encadrant
      const { data: encadrants } = await supabase.from('profiles')
        .select('id').eq('role', 'encadrant').eq('secteur', profile.secteur || '')
      if (encadrants?.length > 0) {
        await supabase.from('notifications').insert(
          encadrants.map(enc => ({
            destinataire_id: enc.id,
            type: 'conge_en_attente',
            titre: `Demande de congés — ${profile?.prenom} ${profile?.nom}`,
            message: `Du ${fmtDate(dateDebutInit)} au ${fmtDate(dateFinInit)} · ${nb} jours`,
            lien: `/assfam/${profile.id}`,
          }))
        )
      }
      // Générer PDF
      await genererPDF(dateDebutInit, dateFinInit)
      setToast('✅ PDF généré et demande enregistrée !')
      setTimeout(() => { onClose() }, 2000)
    } catch(e) {
      setToast('❌ Erreur : ' + e.message)
    }
    setSaving(false)
  }

  async function genererPDF(overrideDebut, overrideFin) {
    const dateDebut = overrideDebut || form.dateDebut
    const dateFin   = overrideFin   || form.dateFin
    // Récupérer la signature (ouvre le canvas si mode=chaque_fois)
    const sigBytes = await getSignatureBytes()
    const W = 841.89, H = 595.28
    const pdfDoc = await PDFDocument.create()
    const page   = pdfDoc.addPage([W, H])
    const font   = await pdfDoc.embedFont(StandardFonts.Helvetica)
    const fontB  = await pdfDoc.embedFont(StandardFonts.HelveticaBold)
    const fontI  = await pdfDoc.embedFont(StandardFonts.HelveticaOblique)
    const BLACK  = rgb(0,0,0)
    const WHITE  = rgb(1,1,1)
    const GRIS   = hexToRgb('#eeeeee')
    const M = 20  // marge
    const TW = W-2*M  // largeur utile

    function dt(text, x, y, size=9, f=font, color=BLACK) {
      page.drawText(String(text||''), { x, y, size, font:f, color })
    }
    function box(x, y, w, h, fill=null, stroke=null, lw=0.5) {
      page.drawRectangle({ x, y, width:w, height:h,
        ...(fill   ? {color:fill}                         : {}),
        ...(stroke ? {borderColor:stroke, borderWidth:lw} : {})
      })
    }
    function ln(x1,y1,x2,y2,color=BLACK,lw=0.5) {
      page.drawLine({start:{x:x1,y:y1},end:{x:x2,y:y2},thickness:lw,color})
    }
    function chk(x, y, checked=false) {
      box(x, y, 9, 9, WHITE, BLACK, 0.7)
      if (checked) dt('x', x+1, y+1, 7, fontB)
    }
    function ctr(text, x, w, y, size=9, f=fontB) {
      const tw = f.widthOfTextAtSize(text, size)
      dt(text, x + Math.max(0,(w-tw)/2), y, size, f)
    }

    // ── LOGO ──────────────────────────────────────────────────────
    const logoImg = await pdfDoc.embedJpg(b64ToBytes(LOGO_B64))
    page.drawImage(logoImg, { x:M, y:H-72, width:56, height:56 })

    // ── TITRE dans cadre ──────────────────────────────────────────
    const txL = M+64, txW = TW-64
    box(txL, H-50, txW, 34, null, BLACK, 1.2)
    ctr('FICHE DE DEMANDE DE CONGES DES ASSISTANTS FAMILIAUX', txL, txW, H-28, 13, fontB)

    // ── ANNEE cadre jaune ─────────────────────────────────────────
    const annee = new Date(dateDebut||Date.now()).getFullYear()
    box(M, H-92, 68, 16, hexToRgb('#fff3cd'), BLACK, 1.2)
    dt(`ANNEE ${annee}`, M+4, H-85, 10, fontB)

    // ── Texte centré ──────────────────────────────────────────────
    ctr('Merci de completer avec precision cette fiche pour chaque demande de conges', M, TW, H-60, 8, font)
    ctr("avant de la transmettre a l'Encadrant Technique - Service Accueil Familial", M, TW, H-70, 8, fontI)

    // ── CASES TERRITOIRE (3 centrees) ─────────────────────────────
    const terrMap = {'Nord':'Albigeois','Ouest':'Gaillacois','Sud':'Autan'}
    const terrLabel = terrMap[secteurLabel] || ''
    const terrs = ['Albigeois','Gaillacois','Autan']
    const terrStep = TW/3
    terrs.forEach((t,i) => {
      const tx = M + i*terrStep + terrStep/2 - 45
      chk(tx, H-105, terrLabel===t)
      dt(`Territoire ${t}`, tx+13, H-101, 9, font)
    })
    ln(M, H-110, W-M, H-110, BLACK, 0.4)

    // ── BANDEAU PARTIE AF ─────────────────────────────────────────
    box(M, H-122, TW, 12, GRIS, BLACK, 0.7)
    ctr("PARTIE A COMPLETER PAR L'ASSISTANT(E) FAMILIAL(E)", M, TW, H-119, 8.5, fontB)

    // ── NOM / ADRESSE ─────────────────────────────────────────────
    const yNA = H-135
    box(M, yNA-18, TW, 18, null, BLACK, 0.7)
    ln(M+TW/2, yNA, M+TW/2, yNA-18, BLACK, 0.5)
    dt('NOM - PRENOM :', M+3, yNA-12, 8.5, fontB)
    dt(`${profile?.nom||''} ${profile?.prenom||''}`, M+78, yNA-12, 9, font)
    dt('ADRESSE :', M+TW/2+4, yNA-12, 8.5, fontB)
    dt(`${profile?.adresse||''} ${profile?.code_postal||''} ${profile?.ville||''}`.trim(), M+TW/2+55, yNA-12, 9, font)

    // ── TABLEAU ENFANTS ───────────────────────────────────────────
    const cW = [TW*0.25, TW*0.17, TW*0.21, TW*0.37]
    const cX = [M, M+cW[0], M+cW[0]+cW[1], M+cW[0]+cW[1]+cW[2]]
    const yTH = yNA-18
    const hdrs = ['Nom et Prenom de chaque enfant accueilli','Territoire concerne','Referent enfant','Proposition eventuelle de relais']
    box(M, yTH-12, TW, 12, GRIS, BLACK, 0.5)
    hdrs.forEach((h,i) => {
      dt(h, cX[i]+3, yTH-9, 7, fontB)
      if(i>0) ln(cX[i], yTH, cX[i], yTH-52, BLACK, 0.4)
    })
    ln(M, yTH, W-M, yTH, BLACK, 0.5)
    ln(M, yTH-12, W-M, yTH-12, BLACK, 0.4)

    const ROW = 16
    const lignes = enfants.length>0 ? [...enfants] : []
    while(lignes.length<3) lignes.push(null)
    lignes.slice(0,4).forEach((enf,i) => {
      const ry = yTH-12-i*ROW
      if(enf?.id) {
        dt(`${enf.prenom} ${enf.nom}`, cX[0]+3, ry-8, 8, font)
        dt(enf.territoire||'', cX[1]+3, ry-8, 8, font)
        const refNom = enf.referent ? `${enf.referent.prenom||''} ${enf.referent.nom||''}`.trim() : ''
        dt(refNom, cX[2]+3, ry-8, 8, font)
        const r1=relaisParEnfant[enf.id], r2=relais2ParEnfant[enf.id]
        const af1=afProfiles.find(a=>a.id===r1), af2=afProfiles.find(a=>a.id===r2)
        const n1=af1?`${af1.prenom} ${af1.nom}`:'', n2=af2?`${af2.prenom} ${af2.nom}`:''
        let rtxt=[n1,n2].filter(Boolean).join(' / ')
        while(rtxt.length>0 && font.widthOfTextAtSize(rtxt,8)>cW[3]-6) rtxt=rtxt.slice(0,-1)
        dt(rtxt, cX[3]+3, ry-8, 8, font)
      }
      ln(M, ry-ROW, W-M, ry-ROW, BLACK, 0.3)
    })
    cX.forEach((x,i)=>{ if(i>0) ln(x, yTH, x, yTH-12-lignes.slice(0,4).length*ROW, BLACK, 0.4) })
    ln(M, yTH, M, yTH-12-lignes.slice(0,4).length*ROW, BLACK, 0.5)
    ln(W-M, yTH, W-M, yTH-12-lignes.slice(0,4).length*ROW, BLACK, 0.5)
    const tBot = yTH-12-lignes.slice(0,4).length*ROW

    // ── DATES — zone sans délimitation ────────────────────────────
    const yD = tBot-14
    dt('Demande de conges du', M, yD, 9, font)
    dt(fmtDate(dateDebut), M+114, yD, 9.5, fontB)
    dt('inclus au', M+172, yD, 9, font)
    dt(fmtDate(dateFin), M+222, yD, 9.5, fontB)
    dt('inclus', M+278, yD, 9, font)
    dt('Date de la demande :', M+344, yD, 9, font)
    dt(fmtDate(form.dateDemandeAffichee), M+448, yD, 9.5, fontB)
    // Date du jour automatique
    const today = new Date()
    const todayStr = today.toLocaleDateString('fr-FR', { day:'2-digit', month:'2-digit', year:'numeric' })
    dt(`Fait le : ${todayStr}`, W-M-160, yD-4, 9, font)
    dt('Signature :', W-M-160, yD-18, 9, font)
    // Insérer l'image de signature si disponible
    if (sigBytes) {
      try {
        const sigImg = await pdfDoc.embedPng(sigBytes)
        const sigDims = sigImg.scale(0.3)
        page.drawImage(sigImg, { x: W-M-155, y: yD-59, width: Math.min(sigDims.width, 150), height: Math.min(sigDims.height, 40) })
      } catch(e) { /* signature non insérée si erreur */ }
    }
    const yD2 = yD-14
    dt('Nombre total de jours demandes :', M, yD2, 9, font)
    dt(`${nbJours} jours`, M+184, yD2, 9.5, fontB)
    ln(M, yD2-62, W-M, yD2-62, BLACK, 0.5)

    // ── BANDEAU DECISION ──────────────────────────────────────────
    const yDecB = yD2-62
    box(M, yDecB-12, TW, 12, GRIS, BLACK, 0.6)
    ctr('DECISION', M, TW, yDecB-9, 9, fontB)

    // ── TABLEAU DECISION ──────────────────────────────────────────
    // Colonnes : DECISION(fus.) | Nom enfant | Val.ESP | Val.ET | NomAF | Famille | Centre | Autre | Départ | Retour
    const dPct = [0.085, 0.175, 0.105, 0.105, 0.115, 0.09, 0.09, 0.065, 0.085, 0.085]
    const dCX = [M]; dPct.forEach(p=>dCX.push(dCX[dCX.length-1]+TW*p))
    const yDH = yDecB-12
    const hHdr1 = 14  // ligne titre groupé Solution
    const hHdr2 = 18  // ligne sous-titres

    // Niveau 1 : fond gris, "Solution d'accueil retenue" centré sur cols 4-7
    box(M, yDH-hHdr1, TW, hHdr1, GRIS, BLACK, 0.5)
    const solX=dCX[4], solW=dCX[8]-dCX[4]
    box(solX, yDH-hHdr1, solW, hHdr1, hexToRgb('#dddddd'), BLACK, 0.5)
    ctr("Solution d'accueil retenue", solX, solW, yDH-10, 7, fontB)
    ln(M, yDH-hHdr1, W-M, yDH-hHdr1, BLACK, 0.4)

    // Niveau 2 : sous-titres colonnes
    box(M, yDH-hHdr1-hHdr2, TW, hHdr2, GRIS, BLACK, 0.5)
    const hdrTxt = ['DECISION',"Nom et Prenom de l'enfant",'Validation Equipe Suivi de Placement','Validation Encadrant Technique SAF',"Nom de l'As. Fam. Relais",'En famille','Centre de vacances','Autre','Date de depart','Date de retour']
    hdrTxt.forEach((t,i)=>{
      const x=dCX[i], w=dCX[i+1]-dCX[i]
      // Texte sur 2 lignes si long
      const words=t.split(' ')
      if(font.widthOfTextAtSize(t,5.5)<w-4) {
        ctr(t, x, w, yDH-hHdr1-11, 5.5, fontB)
      } else {
        const mid=Math.ceil(words.length/2)
        ctr(words.slice(0,mid).join(' '), x, w, yDH-hHdr1-9, 5.5, fontB)
        ctr(words.slice(mid).join(' '),   x, w, yDH-hHdr1-15, 5.5, fontB)
      }
      if(i>0) ln(dCX[i], yDH, dCX[i], yDH-hHdr1-hHdr2, BLACK, 0.4)
    })
    ln(M, yDH, W-M, yDH, BLACK, 0.5)
    ln(M, yDH-hHdr1-hHdr2, W-M, yDH-hHdr1-hHdr2, BLACK, 0.4)

    // Lignes enfants + colonne DECISION fusionnée
    const dROW = 17
    const dBase = yDH-hHdr1-hHdr2
    const nbL = Math.max(enfants.length, 3)
    const decHeight = nbL*dROW
    // Case DECISION fusionnée (toute la hauteur)
    box(dCX[0], dBase-decHeight, dCX[1]-dCX[0], decHeight, null, BLACK, 0.5)
    // Case Accord fusionnée dans col DECISION (bas)
    chk(dCX[0]+4, dBase-decHeight+4, false)
    dt('Accord', dCX[0]+16, dBase-decHeight+6, 7.5, font)

    for(let i=0; i<nbL; i++) {
      const enf=enfants[i]
      const ry=dBase-i*dROW
      if(enf?.id) dt(`${enf.prenom} ${enf.nom}`, dCX[1]+2, ry-9, 7.5, font)
      if(i>0) ln(dCX[1], ry, W-M, ry, BLACK, 0.3)
      dCX.slice(2).forEach(x=>ln(x, dBase, x, dBase-decHeight, BLACK, 0.3))
    }
    ln(dCX[1], dBase, dCX[1], dBase-decHeight, BLACK, 0.4)
    const decBot=dBase-decHeight
    ln(M, decBot, W-M, decBot, BLACK, 0.4)
    ln(M, dBase, M, decBot, BLACK, 0.5)
    ln(W-M, dBase, W-M, decBot, BLACK, 0.5)

    // Refus
    const yRef=decBot-2
    box(M, yRef-16, dCX[1]-M, 12, null, BLACK, 0.5)
    chk(M+3, yRef-13, false)
    dt('Refus', M+16, yRef-11, 8.5, font)
    box(dCX[1], yRef-16, W-M-dCX[1], 12, null, BLACK, 0.5)
    dt('Motif :', dCX[1]+4, yRef-11, 8.5, font)
    ln(M, yRef-16, W-M, yRef-16, BLACK, 0.4)

    // Signature Encadrant — sans case, espacé 3 lignes
    const ySig=yRef-48
    dt("Signature de l'Encadrant Technique :", M+3, ySig, 8.5, fontB)
    dt('Date :', M+TW/2, ySig, 8.5, fontB)
    ln(M, ySig-10, W-M, ySig-10, BLACK, 0.5)

    // ── PARTIE SAF ────────────────────────────────────────────────
    const ySAF=ySig-16
    box(M, ySAF-12, TW, 12, GRIS, BLACK, 0.6)
    ctr('PARTIE RESERVEE AU SAF', M, TW, ySAF-9, 9, fontB)

    // 3 cols + 1 case vide droite sur la même ligne
    const safW = TW*0.75
    const sW   = safW/3
    const sExW = TW*0.25
    // Header 3 cols
    ;['Droit a conges sur l annee','Jours pris','Solde'].forEach((h,i) => {
      box(M+i*sW, ySAF-28, sW, 14, GRIS, BLACK, 0.5)
      ctr(h, M+i*sW, sW, ySAF-24, 7.5, fontB)
      if(i>0) ln(M+i*sW, ySAF-14, M+i*sW, ySAF-46, BLACK, 0.4)
    })
    // Ligne valeurs 3 cols
    box(M, ySAF-46, safW, 18, null, BLACK, 0.5)
    ln(M+sW,   ySAF-28, M+sW,   ySAF-46, BLACK, 0.4)
    ln(M+2*sW, ySAF-28, M+2*sW, ySAF-46, BLACK, 0.4)
    // 4ème case vide — header + valeur alignés à droite
    box(M+safW, ySAF-28, sExW, 14, GRIS, BLACK, 0.5)
    box(M+safW, ySAF-46, sExW, 18, null, BLACK, 0.5)
    ln(M, ySAF-14, W-M, ySAF-14, BLACK, 0.5)

    // ── PIED DE PAGE ──────────────────────────────────────────────
    ln(M+80, 36, W-M-80, 36, BLACK, 0.5)
    ctr('WWW.TARN.FR', M, TW, 30, 9, fontB)
    ctr('DEPARTEMENT DU TARN - 81013 ALBI CEDEX 9 - TEL : 05.63.45.64.64 - Mail : president@tarn.fr', M, TW, 20, 7, font)
    ctr('Tout courrier doit etre adresse de facon impersonnelle a Monsieur le President du Conseil departemental', M, TW, 12, 6.5, fontI)

    // ── TELECHARGER ───────────────────────────────────────────────
    const pdfBytes = await pdfDoc.save()
    const blob = new Blob([pdfBytes], { type:'application/pdf' })
    const url  = URL.createObjectURL(blob)
    const a    = document.createElement('a')
    a.href = url
    a.download = `Demande_conges_${profile?.nom}_${profile?.prenom}_${dateDebut}.pdf`
    a.click()
    URL.revokeObjectURL(url)
  }

  async function soumettreEtGenerer() {
    if (!form.dateDebut || !form.dateFin) {
      setToast('⚠️ Veuillez saisir les dates de congés'); setTimeout(() => setToast(''), 3000); return
    }
    setSaving(true)
    try {
      // 1. Créer l'événement congé dans l'agenda (en attente)
      const dateDebutISO = new Date(`${form.dateDebut}T00:00:00`).toISOString()
      const dateFinISO = new Date(`${form.dateFin}T23:59:00`).toISOString()

      // Préparer les relais par enfant
      const congeRelais = {}
      enfants.forEach(enf => {
        const r1 = relaisParEnfant[enf.id]
        if (r1) {
          const af = afProfiles.find(a => a.id === r1)
          congeRelais[enf.id] = { nom: af ? `${af.prenom} ${af.nom}` : r1, afId: r1, type: 'af' }
        }
      })

      // 1. Créer l'événement congé — 1 seul événement sans enfant_ids (comme Agenda)
      const { error: evtError } = await supabase.from('evenements').insert({
        titre: `Conge AF - ${profile?.prenom} ${profile?.nom}`,
        categorie: 'conge',
        date_debut: dateDebutISO,
        date_fin: dateFinISO,
        notes: form.notes || '',
        af_id: profile.id,
        cree_par: profile.id,
        visible_ase: true,
        source: 'passerelle',
      })
      if (evtError) throw new Error(evtError.message)

      // Créer les événements relais par enfant (J-1 à J+1) — comme Agenda
      const debutRelais = new Date(dateDebutISO); debutRelais.setDate(debutRelais.getDate()-1); debutRelais.setHours(0,0,0,0)
      const finRelais = new Date(dateFinISO); finRelais.setDate(finRelais.getDate()+1); finRelais.setHours(23,59,0,0)
      const relaisRows = []
      enfants.forEach(enf => {
        const afRelaisId = relaisParEnfant[enf.id]
        const af2RelaisId = relais2ParEnfant[enf.id]
        const afObj = afProfiles.find(a => a.id === afRelaisId)
        const nomRelais = afObj ? `${afObj.prenom} ${afObj.nom}` : null
        relaisRows.push({
          titre: nomRelais ? `Relais — famille ${nomRelais}` : `Relais — ${enf.prenom} ${enf.nom} sans relais`,
          categorie: 'relais',
          date_debut: debutRelais.toISOString(),
          date_fin: finRelais.toISOString(),
          notes: `Relais pendant conge AF${nomRelais ? '' : ' — RELAIS NON TROUVE'}`,
          af_id: profile.id,
          cree_par: profile.id,
          visible_ase: true,
          source: 'passerelle',
          relais_type: 'af',
          relais_nom_libre: nomRelais || '',
          enfant_ids: [enf.id],
          ...(afRelaisId ? { participants_ids: [afRelaisId, ...(af2RelaisId ? [af2RelaisId] : [])] } : {})
        })
      })
      if (relaisRows.length > 0) {
        await supabase.from('evenements').insert(relaisRows)
      }

      // 2. Créer l'entrée dans la table conges
      await supabase.from('conges').insert({
        af_id: profile.id,
        date_debut: dateDebutISO,
        date_fin: dateFinISO,
        nb_jours: nbJours,
        statut: 'en_attente',
        notes: form.notes || '',
      })

      // 3. Créer notification pour l'encadrant du secteur
      const { data: encadrants } = await supabase.from('profiles')
        .select('id').eq('role', 'encadrant').eq('secteur', profile.secteur || '')
      if (encadrants && encadrants.length > 0) {
        const notifs = encadrants.map(enc => ({
          destinataire_id: enc.id,
          type: 'conge_en_attente',
          titre: `Demande de congés — ${profile?.prenom} ${profile?.nom}`,
          message: `Du ${fmtDate(form.dateDebut)} au ${fmtDate(form.dateFin)} · ${nbJours} jours`,
          lien: `/assfam/${profile.id}`,
        }))
        await supabase.from('notifications').insert(notifs)
      }

      // 4. Générer le PDF
      await genererPDF(form.dateDebut, form.dateFin)

      setToast('✅ Demande soumise et PDF généré !')
      setTimeout(() => { setToast(''); onClose() }, 2000)
    } catch(e) {
      setToast('❌ Erreur : ' + e.message)
      setTimeout(() => setToast(''), 4000)
    }
    setSaving(false)
  }

  return (
    <>
    {SignatureModal}

    <div style={{ position:'fixed', inset:0, background:'rgba(0,0,0,.55)', zIndex:300, display:'flex', alignItems:'flex-start', justifyContent:'center', overflow:'auto', padding:'24px 0' }}>
      <div style={{ background:'#fff', borderRadius:14, width:640, maxWidth:'95vw', fontFamily:'Sora,sans-serif', boxShadow:'0 8px 40px rgba(0,0,0,.2)' }}>

        {/* Header */}
        <div style={{ background:'linear-gradient(135deg,#1a4b8f,#2563eb)', borderRadius:'14px 14px 0 0', padding:'18px 24px', display:'flex', alignItems:'center', justifyContent:'space-between' }}>
          <div>
            <div style={{ fontSize:17, fontWeight:700, color:'#fff' }}>🏖️ Demande de congés</div>
            <div style={{ fontSize:12, color:'rgba(255,255,255,.75)', marginTop:2 }}>Génère le PDF officiel + crée l'événement dans l'agenda</div>
          </div>
          <button onClick={onClose} style={{ background:'rgba(255,255,255,.2)', border:'none', color:'#fff', borderRadius:8, padding:'6px 12px', cursor:'pointer', fontSize:13 }}>✕</button>
        </div>

        <div style={{ padding:24 }}>

          {/* Infos AF */}
          <div style={{ background:'#f4f6fb', borderRadius:10, padding:'12px 16px', marginBottom:20, fontSize:13 }}>
            <strong>{profile?.prenom} {profile?.nom}</strong>
            {profile?.adresse && <span style={{ color:'#5a6478', marginLeft:8 }}>— {profile.adresse}</span>}
            {secteurLabel && <span style={{ marginLeft:8, padding:'2px 8px', background:'#e8eef8', borderRadius:6, fontSize:11, color:'#1a4b8f', fontWeight:600 }}>Secteur {secteurLabel}</span>}
          </div>

          {/* Dates */}
          <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr 1fr', gap:16, marginBottom:20 }}>
            <div>
              <label style={{ fontSize:11, fontWeight:600, color:'#5a6478', textTransform:'uppercase', display:'block', marginBottom:6 }}>Date de début *</label>
              <input type="date" value={form.dateDebut} onChange={e => setForm(f => ({...f, dateDebut:e.target.value}))}
                style={{ width:'100%', padding:'10px 12px', border:'1.5px solid #dde3f0', borderRadius:8, fontSize:13, fontFamily:'Sora,sans-serif' }} />
            </div>
            <div>
              <label style={{ fontSize:11, fontWeight:600, color:'#5a6478', textTransform:'uppercase', display:'block', marginBottom:6 }}>Date de fin *</label>
              <input type="date" value={form.dateFin} onChange={e => setForm(f => ({...f, dateFin:e.target.value}))}
                style={{ width:'100%', padding:'10px 12px', border:'1.5px solid #dde3f0', borderRadius:8, fontSize:13, fontFamily:'Sora,sans-serif' }} />
            </div>
            <div>
              <label style={{ fontSize:11, fontWeight:600, color:'#5a6478', textTransform:'uppercase', display:'block', marginBottom:6 }}>Nb jours</label>
              <div style={{ padding:'10px 12px', background:'#e8eef8', borderRadius:8, fontSize:15, fontWeight:700, color:'#1a4b8f' }}>
                {nbJours > 0 ? `${nbJours} jours` : '—'}
              </div>
            </div>
          </div>

          {/* Relais par enfant */}
          {enfants.length > 0 && (
            <div style={{ marginBottom:20 }}>
              <label style={{ fontSize:11, fontWeight:600, color:'#5a6478', textTransform:'uppercase', display:'block', marginBottom:10 }}>Relais par enfant</label>
              {enfants.map(enf => (
                <div key={enf.id} style={{ background:'#f9fafb', border:'1px solid #e8eef8', borderRadius:10, padding:'12px 16px', marginBottom:10 }}>
                  <div style={{ fontWeight:600, fontSize:13, marginBottom:8 }}>👶 {enf.prenom} {enf.nom}</div>
                  <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:10 }}>
                    <div>
                      <label style={{ fontSize:10, fontWeight:600, color:'#9aa3b8', textTransform:'uppercase', display:'block', marginBottom:4 }}>Relais 1</label>
                      <select value={relaisParEnfant[enf.id]||''} onChange={e => setRelaisParEnfant(r => ({...r, [enf.id]:e.target.value}))}
                        style={{ width:'100%', padding:'8px 10px', border:'1.5px solid #dde3f0', borderRadius:8, fontSize:12, fontFamily:'Sora,sans-serif' }}>
                        <option value="">— Aucun —</option>
                        {afProfiles.map(a => <option key={a.id} value={a.id}>{a.prenom} {a.nom}</option>)}
                      </select>
                    </div>
                    <div>
                      <label style={{ fontSize:10, fontWeight:600, color:'#9aa3b8', textTransform:'uppercase', display:'block', marginBottom:4 }}>Relais 2 (optionnel)</label>
                      <select value={relais2ParEnfant[enf.id]||''} onChange={e => setRelais2ParEnfant(r => ({...r, [enf.id]:e.target.value}))}
                        style={{ width:'100%', padding:'8px 10px', border:'1.5px solid #dde3f0', borderRadius:8, fontSize:12, fontFamily:'Sora,sans-serif' }}>
                        <option value="">— Aucun —</option>
                        {afProfiles.filter(a => a.id !== relaisParEnfant[enf.id]).map(a => <option key={a.id} value={a.id}>{a.prenom} {a.nom}</option>)}
                      </select>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* Notes */}
          <div style={{ marginBottom:20 }}>
            <label style={{ fontSize:11, fontWeight:600, color:'#5a6478', textTransform:'uppercase', display:'block', marginBottom:6 }}>Notes (optionnel)</label>
            <textarea value={form.notes} onChange={e => setForm(f => ({...f, notes:e.target.value}))}
              placeholder="Informations complémentaires..."
              style={{ width:'100%', padding:'10px 12px', border:'1.5px solid #dde3f0', borderRadius:8, fontSize:13, fontFamily:'Sora,sans-serif', minHeight:70, resize:'vertical', boxSizing:'border-box' }} />
          </div>

          {/* Toast */}
          {toast && (
            <div style={{ padding:'10px 14px', borderRadius:8, background: toast.includes('❌') ? '#fdf0ee' : '#e6f5eb', color: toast.includes('❌') ? '#c0392b' : '#2e8b4a', fontSize:13, marginBottom:16, fontWeight:600 }}>
              {toast}
            </div>
          )}

          {/* Boutons */}
          <div style={{ display:'flex', gap:10, justifyContent:'flex-end' }}>
            <button onClick={onClose} style={{ padding:'10px 20px', borderRadius:8, border:'1px solid #dde3f0', background:'#fff', color:'#5a6478', fontSize:13, cursor:'pointer', fontFamily:'Sora,sans-serif' }}>
              Annuler
            </button>
            <button onClick={() => genererPDF()} style={{ padding:'10px 20px', borderRadius:8, border:'1px solid #c4d4f5', background:'#e8eef8', color:'#1a4b8f', fontSize:13, cursor:'pointer', fontFamily:'Sora,sans-serif', fontWeight:600 }}>
              📄 Aperçu PDF
            </button>
            <button onClick={soumettreEtGenerer} disabled={saving}
              style={{ padding:'10px 20px', borderRadius:8, border:'none', background:'linear-gradient(135deg,#1a4b8f,#2563eb)', color:'#fff', fontSize:13, cursor:'pointer', fontFamily:'Sora,sans-serif', fontWeight:700 }}>
              {saving ? '⏳ Envoi...' : '✅ Soumettre + PDF'}
            </button>
          </div>

        </div>
      </div>
    </div>
    </>
  )
}
